<?php

/* @autogenerated */
declare(strict_types=1);

use PHPUnit\Framework\TestCase;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\AuthenticationResult;

final class AuthenticationResultUnitTest extends TestCase
{
    public function test_factory_wait_magic_link(): void
    {
        $r = AuthenticationResult::waitMagicLink();
        $this->assertFalse($r->valid);
        $this->assertSame(AuthenticationResult::ERR_MAGIC_LINK_SENT, $r->error);
    }

    public function test_factory_wait_newpass(): void
    {
        $r = AuthenticationResult::waitNewpass('https://change.url', 'detail');
        $this->assertFalse($r->valid);
        $this->assertSame(AuthenticationResult::ERR_WAITING_PASSCHANGE_CODE, $r->error);
        $this->assertSame('https://change.url', $r->id);
        $this->assertSame('detail', $r->errorMessage);
    }

    public function test_factory_wait_newuser_verify(): void
    {
        $r = AuthenticationResult::waitNewuserVerify('https://verify.url');
        $this->assertSame(AuthenticationResult::ERR_WAITING_USER_VERIFY, $r->error);
        $this->assertNull($r->errorMessage);
    }

    public function test_factory_mfa_required(): void
    {
        $r = AuthenticationResult::mfaRequired('needs mfa');
        $this->assertSame(AuthenticationResult::ERR_MFA_REQUIRED, $r->error);
        $this->assertSame('needs mfa', $r->errorMessage);
    }

    public function test_factory_new_mfa_required(): void
    {
        $r = AuthenticationResult::newMfaRequired();
        $this->assertSame(AuthenticationResult::ERR_NEW_MFA_REQUIRED, $r->error);
    }

    public function test_factory_consent_required(): void
    {
        $r = AuthenticationResult::consentRequired();
        $this->assertSame(AuthenticationResult::ERR_CONSENT_REQUIRED, $r->error);
    }

    public function test_factory_scopes_consent_required(): void
    {
        $r = AuthenticationResult::scopesConsentRequired();
        $this->assertSame(AuthenticationResult::ERR_SCOPES_CONSENT_REQUIRED, $r->error);
    }

    public function test_factory_new_password_required(): void
    {
        $r = AuthenticationResult::newPasswordRequired();
        $this->assertSame(AuthenticationResult::ERR_NEW_PASSWORD_REQUIRED, $r->error);
    }

    public function test_factory_unknow_user(): void
    {
        $r = AuthenticationResult::unknowUser('t1', 'user@x.com');
        $this->assertSame(AuthenticationResult::ERR_UNKNOW_USER, $r->error);
    }

    public function test_factory_wrong_credentials(): void
    {
        $r = AuthenticationResult::wrongCredentials('t1', 'user@x.com', 'bad pass');
        $this->assertSame(AuthenticationResult::ERR_WRONG_CREDENTIAL, $r->error);
        $this->assertSame('bad pass', $r->errorMessage);
    }

    public function test_factory_not_allowed_access(): void
    {
        $r = AuthenticationResult::notAllowedAccess('t1', 'user@x.com');
        $this->assertSame(AuthenticationResult::ERR_NOT_ALLOWED_ACCESS, $r->error);
    }

    public function test_to_jwt_user_claims(): void
    {
        $r = new AuthenticationResult(
            valid: true,
            id: 'user-1',
            tenant: 'tenant-a',
            scope: 'openid profile',
            audiences: ['api'],
            roles: ['admin'],
            groups: ['g1'],
            name: 'Alice',
            email: 'alice@example.com',
        );

        $claims = $r->toJwtUserClaims('https://iss', 'client-1');

        $this->assertContains('client-1', $claims['aud']);
        $this->assertContains('api', $claims['aud']);
        $this->assertSame('client-1', $claims['azp']);
        $this->assertSame('https://iss', $claims['iss']);
        $this->assertSame('user-1', $claims['sub']);
        $this->assertSame('Alice', $claims['name']);
        $this->assertSame('alice@example.com', $claims['email']);
        $this->assertSame('tenant-a', $claims['tenant']);
    }

    public function test_to_jwt_deduplicates_audiences(): void
    {
        $r = new AuthenticationResult(valid: true, id: 'u', audiences: ['client-1', 'other']);
        $claims = $r->toJwtUserClaims('iss', 'client-1');
        $this->assertSame(array_unique($claims['aud']), $claims['aud']);
    }

    public function test_serialize_and_deserialize_roundtrip(): void
    {
        $r = new AuthenticationResult(
            valid: true,
            id: 'u1',
            tenant: 't1',
            scope: 'openid',
            name: 'Bob',
            email: 'bob@x.com',
            roles: ['user'],
            groups: [],
        );

        $data = $r->serialize();
        $restored = AuthenticationResult::deserialize($data);

        $this->assertTrue($restored->valid);
        $this->assertSame('u1', $restored->id);
        $this->assertSame('t1', $restored->tenant);
        $this->assertSame('openid', $restored->scope);
        $this->assertSame('Bob', $restored->name);
    }

    public function test_deserialize_handles_missing_keys(): void
    {
        $r = AuthenticationResult::deserialize([]);
        $this->assertFalse($r->valid);
        $this->assertNull($r->id);
        $this->assertNull($r->error);
    }
}
